def compute(vars):
    pretax_gain = vars["v1"]
    after_tax_gain = vars["v2"]
    if pretax_gain == 0:
        return None
    change_ratio = (after_tax_gain - pretax_gain) / pretax_gain
    return {
        "value": change_ratio * 100,
        "trace": {
            "old": pretax_gain,
            "new": after_tax_gain,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
